const readableSqlContext = {};
vm.runInNewContext(source.slice(source.indexOf("function sqlLiteral"), source.indexOf("function openDetailSql")), readableSqlContext);
const readableSql = readableSqlContext.readableExecutedSql('SELECT\n    "status" AS "__schemer_d0",\n    pg_catalog.count(*) AS "__schemer_m0"\nFROM "bookstore"."orders"\nGROUP BY\n    "status"\nORDER BY\n    "__schemer_d0" ASC NULLS LAST\nLIMIT %s', [101]);
assert.doesNotMatch(readableSql, /__schemer_|\bAS\b|%s/, "readable SQL must omit implementation aliases and placeholders");
